void reverse ( char *, int );void reverse ( unsigned char *, int );void reverse ( char *theArray, int length ){	int n, i, j;		for (i = 0, j = length - 1; i < j; i++, j--){		n = theArray[i];		theArray[i] = theArray[j];		theArray[j] = n;	}}void reverse ( unsigned char *theArray, int length ){	int n, i, j;		for (i = 0, j = length - 1; i < j; i++, j--){		n = theArray[i];		theArray[i] = theArray[j];		theArray[j] = n;	}}